new = '''def _invoke_with_optional_kwargs(f: Callable[..., Any], **kwargs: Any) -> Any:
    """Pass kwargs to a callable unless it has a parameterless signature."""
    if not kwargs:
        return f()
    try:
        s = inspect.signature(f)
    except (TypeError, ValueError):
        # Some built-in callables do not expose a signature.
        return f(**kwargs)
    if len(s.parameters) == 0:
        return f()
    return f(**kwargs)


class Schema(object):
'''
assert text.count(old) == 1
path.write_text(text.replace(old, new))

